cd /private/tmp/claude-501/-private-tmp-live-spec-roadmap-wave/eed6f581-a11a-4a22-a5ad-a564013623f3/scratchpad/matrixcheck
awk '
/^### \[node:/ {
  if (name != "") { close(outfile) }
  line=$0
  gsub(/^### \[node: /,"",line)
  gsub(/\]$/,"",line)
  gsub(/ \[target\]$/,"",line)
  name=line
  outfile = "node_" name ".md"
  print $0 > outfile
  next
}
/^## / && name != "" && $0 !~ /^### \[node:/ {
  # a level-2 heading ends the node blocks section
  if (name != "" && stopname=="") { stopname=name }
}
{ if (name != "") print $0 > outfile }
' base_TEST_MATRIX.md
